verus! {

    /// Returns the maximum element of a non-empty vector of i32.
    /// 
    /// Requirements:
    /// - `a.len() >= 1`
    /// 
    /// Ensures:
    /// - `result` is ≥ every element of `a`.
    /// - `result` is equal to some element of `a`.
    fn max_array(a: &Vec<i32>) -> (result: i32)
        requires
            a.len() >= 1,
        ensures
            // result is at least as large as every element
            forall j: usize :: j < a.len() ==> result >= a[j],
        ensures
            // result is equal to one of the elements
            exists k: usize :: k < a.len() && result == a[k],
    {
        // We'll process the prefix a[0..i), maintaining `max` as its maximum.
        let mut i: usize = 1;
        let mut max = a[0];

        while i < a.len()
            invariant
                // i always in [1, a.len()]
                1 <= i && i <= a.len(),
            invariant
                // max is ≥ every element in the processed prefix
                forall j: usize :: j < i ==> max >= a[j],
            invariant
                // max is equal to some element in the processed prefix
                exists k: usize :: k < i && max == a[k],
            decreases
                // measure to ensure termination
                a.len() - i,
        {
            let v = a[i];
            if v > max {
                max = v;
            }
            i += 1;
        }

        result = max;
    }

}